import { test, expect } from "../helpers/theme-browser";
import { randomUUID } from "node:crypto";
import { mkdir } from "node:fs/promises";

for (const appearance of ["purple", "vercel"]) {
  for (const mode of ["light", "dark"]) {
    test(`progress card hover: ${appearance} ${mode}`, async ({
      page,
      themeUser,
      themeDatabase,
      isMobile,
    }, info) => {
      const before = process.env.PROGRESS_CAPTURE_BEFORE === "1";
      const directory = `/tmp/mailloop-progress-${before ? "before" : "after"}/${info.project.name}-${appearance}-${mode}`;
      await mkdir(directory, { recursive: true });
      await page.addInitScript(
        ({ appearance, mode }) => {
          localStorage.setItem("mailloop-appearance", appearance);
          localStorage.setItem("mailloop-theme", mode);
        },
        { appearance, mode },
      );
      const template = randomUUID();
      const contact = randomUUID();
      const campaign = randomUUID();
      await themeDatabase.query(
        `INSERT INTO "Template" (id,"userId",name,subject,body) VALUES ($1,$2,'Progress','Hello','Hello')`,
        [template, themeUser],
      );
      await themeDatabase.query(
        `INSERT INTO "Contact" (id,"userId",name,email) VALUES ($1,$2,'Alex','[REDACTED_EMAIL]')`,
        [contact, themeUser],
      );
      await themeDatabase.query(
        `INSERT INTO "Campaign" (id,"userId","templateId",status) VALUES ($1,$2,$3,'QUEUED')`,
        [campaign, themeUser, template],
      );
      for (const status of ["SENT", "QUEUED", "FAILED", "CANCELLED"]) {
        await themeDatabase.query(
          `INSERT INTO "Send" (id,"campaignId","contactId",status,"deliveryState","dispatchedAt") VALUES ($1,$2,$3,$4::"SendStatus",$5::"DeliveryState",now())`,
          [
            randomUUID(),
            campaign,
            contact,
            status,
            status === "QUEUED" ? "READY" : "DONE",
          ],
        );
      }
      await page.goto(`/history?campaign=${campaign}`);
      await expect(page.locator("html")).toHaveAttribute(
        "data-appearance",
        appearance,
      );
      await expect(page.locator("html")).toHaveAttribute("data-theme", mode);
      const panel = page.getByRole("region", {
        name: "Campaign delivery progress",
      });
      const cards = panel.locator("dl > div");
      await expect(cards).toHaveCount(4);
      await panel.scrollIntoViewIfNeeded();
      await page.mouse.move(0, 0);
      await page.evaluate(() => document.fonts.ready);
      await page.waitForTimeout(400);
      const paint = () =>
        cards.evaluateAll((elements) =>
          elements.map((element) => {
            const s = getComputedStyle(element);
            const rect = element.getBoundingClientRect();
            return {
              x: rect.x + scrollX,
              y: rect.y + scrollY,
              width: rect.width,
              height: rect.height,
              background: s.backgroundColor,
              border: s.borderColor,
              shadow: s.boxShadow,
              transform: s.transform,
              transition: s.transitionDuration,
            };
          }),
        );
      const resting = await paint();
      const panelLayout = () =>
        panel.evaluate((element) => {
          const rect = element.getBoundingClientRect();
          return {
            x: rect.x + scrollX,
            y: rect.y + scrollY,
            width: rect.width,
            height: rect.height,
          };
        });
      await panel.locator("dl").screenshot({ path: `${directory}/rest.png` });
      for (let index = 0; index < 4; index++) {
        const card = cards.nth(index);
        const panelBefore = await panelLayout();
        if (isMobile) await card.tap();
        else await card.hover();
        await page.waitForTimeout(400);
        const hovered = await paint();
        await panel.screenshot({ path: `${directory}/hover-${index}.png` });
        if (!before) {
          for (let other = 0; other < 4; other++) {
            expect(hovered[other].width).toBe(resting[other].width);
            expect(hovered[other].height).toBe(resting[other].height);
            expect(hovered[other].x).toBe(resting[other].x);
            expect(hovered[other].y).toBeCloseTo(
              resting[other].y + (!isMobile && other === index ? -6 : 0),
              1,
            );
          }
          expect(await panelLayout()).toEqual(panelBefore);
          if (isMobile) expect(hovered).toEqual(resting);
          else {
            expect(hovered[index].background).not.toBe(
              resting[index].background,
            );
            expect(hovered[index].border).not.toBe(resting[index].border);
            expect(hovered[index].shadow).not.toBe("none");
            expect(hovered[index].transition).toContain("0.35s");
          }
        }
        await page.mouse.move(0, 0);
        await page.waitForTimeout(400);
        if (!before) expect(await paint()).toEqual(resting);
      }
      await page.emulateMedia({ reducedMotion: "reduce" });
      await cards.first().hover();
      await page.waitForTimeout(400);
      if (!before) {
        const reduced = (await paint())[0];
        expect(reduced.transform).toBe("none");
        expect(reduced.y).toBe(resting[0].y);
        if (!isMobile)
          expect(reduced.background).not.toBe(resting[0].background);
      }
      await panel.screenshot({ path: `${directory}/reduced.png` });
      expect(
        await page.evaluate(
          () => document.documentElement.scrollWidth <= innerWidth,
        ),
      ).toBe(true);
    });
  }
}
